query:
query Billboard(
  $countryId: String!
  $movieId: String!
  $cinemas: String!
  $timezone: String
) {
  billboard(
    countryId: $countryId
    movieId: $movieId
    cinemas: $cinemas
    timezone: $timezone
  ) {
    dates
    schedules {
      cinemaId
      cityId
      movieId
      dates {
        date
        languages {
          language
          displayLanguage
          showtimes {
            format {
              icon
              name
            }
            sessionId
            datetime
            screen
            experience {
              icon
              name
            }
            movieVistaId
            cinemaVistaId
            alerts {
              section
              title
              message
            }
            availability
            isAllocatedSeating
          }
        }
      }
    }
  }
}
